"""Write CASES.md: every calibration case with its diff and expected verdicts, for human review."""

from __future__ import annotations

import re

from cases import DEFAULT_VERDICT, EVAL_DIR, load_cases

OUTPUT = EVAL_DIR / "CASES.md"


def fence_for(text: str) -> str:
    longest = max((len(run) for run in re.findall(r"`+", text)), default=0)
    return "`" * max(3, longest + 1)


def main() -> None:
    cases = load_cases()
    rules = sorted(cases[0].expected)
    lines = [
        "# Judge calibration cases",
        "",
        "Generated by `evals/judge/review.py` from `cases.yaml` and `cases/`. Review every label:",
        "would you grade this change the same way against each rule?",
        "",
        "| Case | Tags | Expected fail | Expected pass | Either |",
        "|---|---|---|---|---|",
    ]
    for case in cases:
        def ids(match):
            return ", ".join(r for r in rules if match(case.expected[r])) or "-"
        lines.append(
            f"| [{case.id}](#{case.id}) | {', '.join(case.tags)} "
            f"| {ids(lambda v: v == {'fail'})} | {ids(lambda v: v == {'pass'})} "
            f"| {ids(lambda v: len(v) > 1)} |"
        )
    for case in cases:
        lines += ["", f"## {case.id}", "", f"**{case.title}**", "", "| Rule | Expected | Why |",
                  "|---|---|---|"]
        for rule in rules:
            verdicts = " or ".join(sorted(case.expected[rule]))
            if verdicts != DEFAULT_VERDICT or rule in case.notes:
                lines.append(f"| {rule} | {verdicts} | {case.notes.get(rule, '')} |")
        lines.append(f"| all other rules | {DEFAULT_VERDICT} | |")
        fence = fence_for(case.diff)
        lines += ["", f"{fence}diff", case.diff.rstrip("\n"), fence]
    OUTPUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {OUTPUT.relative_to(EVAL_DIR.parent.parent)} ({len(cases)} cases)")


if __name__ == "__main__":
    main()
